it('preserves a string rejection as the onError cause', async () => {
  const reason = 'string boom';
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  let receivedError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      receivedError = error;
    },
  };
  const session: ChatSession = {
    sessionId: 'test-session',
    userId: 'user-1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };

  await createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {hooks})
    .processMessage(session)
    .catch(() => undefined);

  expect(receivedError?.cause).toBe(reason);
});
EOF
